def sha(p):
    h=hashlib.sha256()
    with open(p,'rb') as f:
        for b in iter(lambda:f.read(8<<20),b''):h.update(b)
    return h.hexdigest()
def digest(x):return hashlib.sha256(json.dumps(x,sort_keys=True).encode()).hexdigest()
def read(p):return json.loads(Path(p).read_text(encoding='utf-8'))
def write(p,x):
    p=Path(p);p.parent.mkdir(parents=True,exist_ok=True);t=p.with_suffix(p.suffix+'.tmp')
    t.write_text(json.dumps(x,indent=2,allow_nan=False),encoding='utf-8');os.replace(t,p)

def verify_attached(root):
    root=Path(root);e=read(root/'experiment.json')
    if e['name']!='PhotoAug_1st' or e['tag']!=RUN_TAG or e['source_hashes']!=SOURCE_HASHES:
        raise ValueError('Different experiment/code; nothing overwritten')
    manifest=read(root/'artifact_manifest.json')
    for name,v in manifest.items():
        p=root/name
        if not p.resolve().is_relative_to(root.resolve()) or p.stat().st_size!=v['bytes'] or sha(p)!=v['sha256']:
            raise ValueError('Archive hash/size mismatch: '+name)
    return root

