import numpy as np,h5py,torch
torch.set_num_threads(1)
sys.path.insert(0,str(code))
from photoaug_model import Model,load_common,common_state
from photoaug_worker import state_hash
from photoaug_dashboard import Dashboard
dashboard=Dashboard(PHASE,output)
stage=output/'sessions'/phasekey;stage.mkdir(parents=True,exist_ok=True)

def prepare_data():
    names={'train':'train_qb.h5','val':'valid_qb.h5','RR':'test_qb_multiExm1.h5','FR':'test_qb_OrigScale_multiExm1.h5'}
    expected={'train':17139,'val':1905,'RR':20,'FR':20}
    root=Path(DATA_ROOT) if DATA_ROOT else Path('/kaggle/input')
    result={}
    for split,name in names.items():
        candidates=[p for p in root.rglob('*.h5') if (p.name==name or p.name.endswith('__'+name)) and not p.name.startswith('._') and '__._' not in p.name]
        if len(candidates)!=1:raise ValueError(f'{split}: expected one QB {name}, found {candidates}. Set DATA_ROOT to the Dataset folder only.')
        p=candidates[0];dashboard.refresh(split+' 데이터 유한값·범위·SHA-256 검사 중')
        entry={'path':str(p),'sha256':sha(p),'bytes':p.stat().st_size,'arrays':{}}
        if split in EXPECTED_DATA_HASHES and entry['sha256']!=EXPECTED_DATA_HASHES[split]:
            raise ValueError(split+': differs from 33 archived H5 hash; do not silently substitute data')
        with h5py.File(p) as h:
            keys=('pan','lms','ms') if split=='FR' else ('pan','lms','ms','gt')
            shapes={k:tuple(h[k].shape) for k in keys};n,c,height,width=shapes['lms']
            if n!=expected[split] or c!=4 or height%4 or width%4:raise ValueError('Unexpected QB split/NCHW '+str(shapes))
            if shapes['pan']!=(n,1,height,width) or shapes['ms']!=(n,4,height//4,width//4):raise ValueError('PAN/MS shapes differ')
            if split!='FR' and shapes['gt']!=shapes['lms']:raise ValueError('GT shape differs')
            if split in ('train','val') and (height,width)!=(64,64):raise ValueError('33 training patches must be 64x64')
            for k in keys:
                ds=h[k];lo=float('inf');hi=-float('inf')
                for start in range(0,n,32):
                    a=np.asarray(ds[start:start+32],dtype=np.float32)
                    if not np.isfinite(a).all():raise ValueError(split+'/'+k+': nonfinite data')
                    lo=min(lo,float(a.min()));hi=max(hi,float(a.max()))
                # Keep actual tiny negative interpolation roundoff and supplied LMS overshoot.
                if k in ('pan','ms','gt') and (lo < -1e-4 or hi>2047.0001 or hi<=1):raise ValueError(f'{split}/{k}: unexpected raw DN [{lo},{hi}]')
                entry['arrays'][k]={'shape':list(ds.shape),'dtype':str(ds.dtype),'raw_min':lo,'raw_max':hi}
            used=min(n,128 if split=='train' else 32) if PHASE=='smoke' and split in ('train','val') else n
            entry.update(used_samples=used,resident_fp32_bytes=sum(used*math.prod(shapes[k][1:])*4 for k in keys) if split in ('train','val') else 0)
        result[split]=entry;dashboard.data_checked(split,entry)
    raw={s:{'sha256':e['sha256'],'bytes':e['bytes'],'arrays':e['arrays']} for s,e in result.items()}
    if (output/'data_contract.json').exists() and read(output/'data_contract.json')!=raw:raise ValueError('Data contents differ from previous session')
    write(output/'data_contract.json',raw);write(stage/'data_manifest.json',result)
    return result

def environment():
    gpu=[{'index':i,'name':torch.cuda.get_device_name(i),'memory_bytes':torch.cuda.get_device_properties(i).total_memory,
          'capability':list(torch.cuda.get_device_capability(i))} for i in range(torch.cuda.device_count())]
    if len(gpu)!=2 or any(gpu[0][k]!=gpu[1][k] for k in ('name','memory_bytes','capability')):
        raise RuntimeError('Require exactly two matching GPUs; no silent fallback')
    e={'python':sys.version,'torch':str(torch.__version__),'numpy':np.__version__,'h5py':h5py.__version__,
       'cuda':torch.version.cuda,'cudnn':torch.backends.cudnn.version(),'gpu':gpu,
       'packages':{m:__import__('importlib.metadata',fromlist=['version']).version(m) for m in ('scipy','scikit-image','matplotlib','Pillow')}}
    if (output/'environment_contract.json').exists() and read(output/'environment_contract.json')!=e:
        raise ValueError('Software/GPU conditions changed; existing results preserved. Use the same environment or a new RUN_TAG.')
    write(output/'environment_contract.json',e);write(stage/('environment_'+str(time.time_ns())+'.json'),e)
    try:(stage/('nvidia_smi_'+str(time.time_ns())+'.txt')).write_text(subprocess.check_output(['nvidia-smi'],text=True,timeout=10))
    except (OSError,subprocess.SubprocessError):pass
    return e

def task(family,seed,label,gpu,epochs,job_type='train',stop=0):
    root=output/family/f'seed_{seed}';root.mkdir(parents=True,exist_ok=True)
    initial=root/'initial.pt'
    if not initial.exists():
        if job_type=='test' or any(root.rglob('latest.pt')):raise ValueError('Common initialization is missing')
        torch.manual_seed(seed);m=Model('baseline').eval();torch.save(common_state(m),initial)
        (root/'initial.sha256').write_text(sha(initial));del m
    if sha(initial)!=(root/'initial.sha256').read_text():raise ValueError('Initial weights changed')
    cond={'basis':protocol['basis'],'data_contract':digest(read(output/'data_contract.json')),
          'environment_contract':digest(env),'family':family,'seed':seed,'label':label,'epochs':epochs,
          'initial_sha256':sha(initial),'arm':'aug' if label=='aug' else 'baseline','augmentation':'joint gain[0.9,1.1],offset[-0.01,0.01]; inverse before original-unit MSE','micro':32,'effective_batch':64,
          'samples':{s:data[s]['used_samples'] for s in ('train','val')}}
    cfg={'output':str(root),'code_root':str(code),'seed':seed,'arm':'aug' if label=='aug' else 'baseline','augmentation':'joint gain[0.9,1.1],offset[-0.01,0.01]; inverse before original-unit MSE','epochs':epochs,'conditions':cond,
         'fingerprint':digest(cond),'data':data,'selection':{'indices':[1,8,11,13,19]},'batch':64,'micro':32,
         'amp':True,'lr':1e-4,'deadline':deadline,'reserve_gib':4,'log_seconds':20,
         'job_type':job_type,'stop_after_group':stop,'smoke_deterministic':family.startswith('smoke'),
         'smoke_evaluation':family.startswith('smoke')}
    path=root/(label+'_config.json')
    if path.exists() and read(path)['fingerprint']!=cfg['fingerprint']:raise ValueError('Job conditions differ')
    write(path,cfg)
    return {'gpu':gpu,'label':label,'folder':root/label,'config':cfg,'path':path}

def completion(j,test=False):
    p=j['folder']/('evaluation_complete.json' if test else 'training_complete.json')
    if not p.exists():return False
    if test:
        m=read(p)
        if m['fingerprint']!=j['config']['fingerprint']:raise ValueError('Evaluation fingerprint differs')
        for k in ('best','latest'):
            if m[k+'_sha256']!=sha(j['folder']/(k+'.pt')) or m['results_sha256'][k]!=sha(j['folder']/'evaluations'/k/'results.json'):
                raise ValueError('Evaluated weights/results changed')
    else:
        m=read(p)
        if m.get('fingerprint')!=j['config']['fingerprint']:raise ValueError('Training proof fingerprint differs')
        if m['epochs']!=j['config']['epochs'] or any(m[k+'_sha256']!=sha(j['folder']/(k+'.pt')) for k in ('best','latest')):
            raise ValueError('Training proof differs')
    return True

def run(jobs,test=False):
    processes=[]
    try:
        for j in jobs:
            j['folder'].mkdir(exist_ok=True);dashboard.starting(j,0)
            dashboard.rows[j['gpu']]['context']=f"{PHASE} · {j['folder'].parent.name} · {'국소 MS 통계' if j['config']['arm']=='aug' else '33번 N1 전체 통계'}"
            if completion(j,test):dashboard.finish(j,skipped=True);continue
            if time.time()>=deadline:continue
            log=open(j['folder']/'worker.log','a',encoding='utf-8');environ=os.environ.copy()
            environ.update(CUDA_VISIBLE_DEVICES=str(j['gpu']),OMP_NUM_THREADS='1',MKL_NUM_THREADS='1',PYTHONDONTWRITEBYTECODE='1')
            p=subprocess.Popen([sys.executable,str(code/'photoaug_worker.py'),'--config',str(j['path']),'--label',j['label'],'--gpu',str(j['gpu'])],
                               env=environ,stdout=log,stderr=subprocess.STDOUT)
            processes.append((p,j,log,time.monotonic()))
        while any(p.poll() is None for p,_,_,_ in processes):
            for p,j,_,_ in processes:
                path=j['folder']/'status.json'
                if path.exists():dashboard.observe(j['gpu'],read(path))
                if p.poll() not in (None,0):raise RuntimeError('Worker failed: '+str(j['folder']/'worker.log'))
            dashboard.refresh('동시에 두 GPU에서 비교 실행 중 · 종료 예산 도달 시 체크포인트 저장')
            if time.time()>=deadline:
                for p,_,_,_ in processes:
                    if p.poll() is None:p.send_signal(signal.SIGINT)
            time.sleep(5)
        for p,j,_,tick in processes:
            if p.returncode:raise RuntimeError('Worker failed: '+str(j['folder']/'worker.log'))
            write(j['folder']/('session_'+str(time.time_ns())+'.json'),{'job_type':j['config']['job_type'],'gpu':j['gpu'],
                'wall_seconds_includes_possible_wait_for_other_arm':time.monotonic()-tick})
            dashboard.finish(j)
    finally:
        for p,_,_,_ in processes:
            if p.poll() is None:p.send_signal(signal.SIGINT)
        for p,j,log,_ in processes:
            if p.poll() is None:
                try:p.wait(timeout=45)
                except subprocess.TimeoutExpired:p.terminate();p.wait(timeout=10)
            log.close()
            if p.returncode:dashboard.finish(j,p.returncode)
        dashboard.refresh()

def pair_check(jobs):
    a,b=[j['folder'] for j in jobs]
    ia,ib=[read(p/'initialization.json') for p in (a,b)]
    ca,cb=[torch.load(p/'latest.pt',map_location='cpu',weights_only=False) for p in (a,b)]
    checks={'common_initial_weights_equal':ia['common_state_sha256']==ib['common_state_sha256'],
            'epoch_orders_equal':ca['order_history']==cb['order_history'],'augmentation_plans_equal':ca['order_history']==cb['order_history'],
            'epochs_equal':ca['epoch']==cb['epoch']==jobs[0]['config']['epochs'],
            'architecture_differs':False,'normalization_differs':False,'training_augmentation_differs':True,'initial_outputs_expected_equal':True,'final_weights_expected_to_differ':True,
            'amp_skipped_steps':{'baseline':ca['skipped_amp_steps'],'aug':cb['skipped_amp_steps']}}
    if not all(checks[k] for k in ('common_initial_weights_equal','epoch_orders_equal','augmentation_plans_equal','epochs_equal')):raise ValueError('Controlled pair checks failed')
    write(a.parent/'pair_checks.json',checks)

def digest_optimizer(ck):
    h=hashlib.sha256()
    def visit(x):
        if isinstance(x,torch.Tensor):
            h.update(str((str(x.dtype),tuple(x.shape))).encode());h.update(x.detach().cpu().contiguous().numpy().tobytes())
        elif isinstance(x,dict):
            for k in sorted(x,key=str):h.update(str(k).encode());visit(x[k])
        elif isinstance(x,(tuple,list)):
            h.update(str(type(x)).encode())
            for v in x:visit(v)
        else:h.update(repr(x).encode())
    visit({'optimizer':ck['optimizer'],'scaler':ck['scaler']})
    return h.hexdigest()

def summarize():
    rows=[];scenes=[]
    for seed in (42,43,44):
        root=output/'final'/f'seed_{seed}'
        for kind in ('best','latest'):
            files=[root/a/'evaluations'/kind/'results.json' for a in ('baseline','aug')]
            if not all(p.exists() for p in files):continue
            proofs=[root/a/'evaluation_complete.json' for a in ('baseline','aug')]
            if not all(p.exists() for p in proofs):continue
            for arm,p in zip(('baseline','aug'),proofs):
                proof=read(p)
                if proof['results_sha256'][kind]!=sha(root/arm/'evaluations'/kind/'results.json'):raise ValueError('Evaluation evidence changed')
                if proof[kind+'_sha256']!=sha(root/arm/(kind+'.pt')):raise ValueError('Evaluation weights changed')
            rs=[read(p) for p in files]
            for split in ('RR','FR'):
                for metric in rs[0]['splits'][split]['mean']:
                    a,b=[r['splits'][split]['mean'][metric] for r in rs]
                    rows.append({'seed':seed,'checkpoint':kind,'split':split,'metric':metric,'baseline':a,'aug':b,'aug_minus_baseline':b-a})
                ss=[read(root/a/'evaluations'/kind/(split+'_per_scene.json')) for a in ('baseline','aug')]
                if [r['scene_index'] for r in ss[0]]!=[r['scene_index'] for r in ss[1]]:raise ValueError('Scene IDs differ')
                scenes.extend({'seed':seed,'checkpoint':kind,'split':split,'scene_index':a['scene_index'],**{k:b[k]-a[k] for k in a if k!='scene_index'}} for a,b in zip(*ss))
    write(output/'paired_scene_deltas.json',scenes)
    if not rows:return
    with open(output/'comparison.csv','w',newline='',encoding='utf-8-sig') as f:
        w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
    groups={}
    for r in rows:groups.setdefault((r['checkpoint'],r['split'],r['metric']),[]).append(r)
    stats=[]
    for (kind,split,metric),values in groups.items():
        item={'checkpoint':kind,'split':split,'metric':metric,'n_seeds':len(values)}
        for key in ('baseline','aug','aug_minus_baseline'):
            x=[r[key] for r in values];item[key+'_mean']=float(np.mean(x));item[key+'_sample_std']=float(np.std(x,ddof=1)) if len(x)>1 else None
        stats.append(item)
    write(output/'seed_statistics.json',stats)
    md=['# 원본 SSA-MRN 밝기·대비 증강 비교','', 'best: validation MSE 선택. latest: 보조 결과. Q2n/SCC/FR 지표는 MATLAB 대응 미검증입니다.',
        '','|seed|가중치|분할|지표|original N0|augmentation|차이|','|---|---|---|---|---:|---:|---:|']
    md.extend(f"|{r['seed']}|{r['checkpoint']}|{r['split']}|{r['metric']}|{r['baseline']:.6g}|{r['aug']:.6g}|{r['aug_minus_baseline']:+.6g}|" for r in rows)
    md.extend(['','차이는 augmentation − original N0입니다. PSNR/SCC/Q2n/QNR은 양수, SAM/ERGAS/Dλ/Ds는 음수가 개선 방향입니다.',
               '한 seed의 결과로 반복 재현을 주장하지 않습니다. RR 이득과 FR 악화가 함께 나타나면 부분 개선입니다.'])
    (output/'comparison.md').write_text('\n'.join(md),encoding='utf-8')

def curves():
    import matplotlib;matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    for root in (output/'smoke',output/'final'):
        if not root.exists():continue
        for seedroot in root.glob('seed_*'):
            fig,axes=plt.subplots(1,4,figsize=(15,3));has=False
            for arm in ('baseline','aug'):
                p=seedroot/arm/'history.json'
                if not p.exists():continue
                h=read(p);has=has or bool(h)
                for ax,k in zip(axes,('train_mse','val_mse','val_sam','val_psnr')):
                    ax.plot([r['epoch'] for r in h],[r[k] for r in h],label=arm);ax.set_title(k);ax.set_xlabel('epoch');ax.grid(alpha=.2)
            if has:
                axes[0].legend();fig.tight_layout();fig.savefig(seedroot/'curves.png',dpi=140)
            plt.close(fig)

def package(note):
    write(stage/'status.json',{'note':note,'phase':PHASE,'seed':SEED,'remote_preservation_verified':False})
    try:curves();summarize()
    except Exception as exc:write(stage/'summary_error.json',{'error':str(exc)});print('집계 오류: 원본 증거를 보관합니다:',exc)
    inventory={p.relative_to(output).as_posix():{'bytes':p.stat().st_size,'sha256':sha(p)} for p in output.rglob('*')
               if p.is_file() and p.name!='artifact_manifest.json' and not p.name.endswith('.tmp') and '__pycache__' not in p.parts}
    write(output/'artifact_manifest.json',inventory)
    archive=output.parent/(RUN_TAG+'_'+phasekey+'_results.zip');temp=archive.with_suffix('.tmp')
    with zipfile.ZipFile(temp,'w',zipfile.ZIP_DEFLATED,compresslevel=1) as z:
        for name in list(inventory)+['artifact_manifest.json']:z.write(output/name,RUN_TAG+'/'+name)
    os.replace(temp,archive);print(note,'\nZIP:',archive,'\nSHA-256:',sha(archive),flush=True)
    dashboard.refresh(note+'\nZIP: '+archive.name+'\nSaved Output 저장 및 다운로드가 필요합니다.')
    from IPython.display import display,FileLink
    display(FileLink(str(archive)))

note='중단/오류: 보존된 체크포인트만 확인하고 같은 단계를 재실행하세요.'
import fcntl
controller_lock=(output/'.controller.lock').open('a+b')
try:fcntl.flock(controller_lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
except BlockingIOError:
    controller_lock.close()
    raise RuntimeError('This experiment already has an active controller; do not launch a duplicate cell')
try:
    env=environment();data=prepare_data()
    if PHASE=='smoke':
        jobs=[task('smoke',42,a,g,2,stop=1) for g,a in enumerate(('baseline','aug'))]
        if not all(completion(j) for j in jobs):
            run(jobs)
            for j in jobs:
                if (j['folder']/'latest.pt').exists():
                    ck=torch.load(j['folder']/'latest.pt',map_location='cpu',weights_only=False)
                    if ck['epoch']==0 and ck['next_sample_position']==64:
                        write(j['folder']/'forced_pause_seen.json',{'position':64,'optimizer_saved':True,'scaler_saved':True})
            for j in jobs:j['config']['stop_after_group']=0;write(j['path'],j['config'])
            if time.time()<deadline:run(jobs)
        if all(completion(j) for j in jobs):
            pair_check(jobs)
            refs=[task('smoke_reference',42,a,g,2) for g,a in enumerate(('baseline','aug'))]
            run(refs)
            if all(completion(j) for j in refs):
                checks=[]
                for j,r in zip(jobs,refs):
                    a,b=[torch.load(q['folder']/'latest.pt',map_location='cpu',weights_only=False) for q in (j,r)]
                    checks.append({'arm':j['label'],'forced_pause_seen':(j['folder']/'forced_pause_seen.json').exists(),
                        'weights_exact':state_hash(a['model'])==state_hash(b['model']),
                        'orders_exact':a['order_history']==b['order_history'],
                        'history_primary_exact':all(x[k]==y[k] for x,y in zip(a['history'],b['history']) for k in ('train_mse','val_mse','val_psnr','val_sam','lr')),
                        'optimizer_scaler_equal':digest_optimizer(a)==digest_optimizer(b)})
                passed=all(v for c in checks for k,v in c.items() if k!='arm')
                write(output/'smoke_resume_checks.json',{'passed':passed,'checks':checks,'excluded_from_final':True})
                if not passed:raise ValueError('Smoke resume differs; no final training allowed')
                tests=[task('smoke',42,a,g,2,'test') for g,a in enumerate(('baseline','aug'))]
                run(tests,test=True)
                if all(completion(j,True) for j in tests):
                    write(output/'smoke_checks.json',{'passed':True,'excluded_from_final':True,'evaluation':'first 2 validation inputs only; not held-out test'})
                    note='Smoke 통과: 저장·재개·평가 확인. 최종 성능 비교에 포함하지 않습니다.'
    else:
        if not read(output/'smoke_checks.json')['passed']:raise ValueError('Smoke must pass before final training')
        test=PHASE=='final_test'
        if SEED>42 and not (output/'final'/f'seed_{SEED-1}'/'pair_checks.json').exists():raise ValueError('Previous seed training is incomplete')
        if SEED>42 and not all((output/'final'/f'seed_{SEED-1}'/a/'evaluation_complete.json').exists() for a in ('baseline','aug')):
            raise ValueError('Finish previous seed test first; settings remain frozen')
        jobs=[task('final',SEED,a,g,100,'test' if test else 'train') for g,a in enumerate(('baseline','aug'))]
        if test:
            if not all(completion(j) for j in jobs):raise ValueError('Finish BOTH arms of this seed before testing')
            pair_check(jobs)
        run(jobs,test=test)
        if all(completion(j,test) for j in jobs):
            if not test:pair_check(jobs)
            note=phasekey+' 완료. '+('이 seed의 test 셀을 실행하세요.' if not test else '완료된 seed만 집계했습니다. test로 설정을 변경하지 마세요.')
finally:
    try:package(note)
    finally:
        fcntl.flock(controller_lock,fcntl.LOCK_UN);controller_lock.close()
